import { useState, useEffect, Component } from "react";
import type { ReactNode, ErrorInfo } from "react";
import { SlotPanel } from "../components/slot-panel";
import { QrHint } from "../components/qr-hint";
import { Loader2Icon, AlertCircleIcon, MonitorIcon } from "lucide-react";

// ---- error boundary ---------------------------------------------------------

interface ErrorBoundaryState {
  error: Error | null;
}

class StageErrorBoundary extends Component<{ children: ReactNode }, ErrorBoundaryState> {
  state: ErrorBoundaryState = { error: null };

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[StageView] render error", error, info);
  }

  render() {
    if (this.state.error) {
      return (
        <div className="flex flex-col items-center justify-center h-screen bg-[#080810] gap-4">
          <AlertCircleIcon className="size-8 text-red-10" />
          <p className="text-headline text-gray-9">Display error — please reload</p>
          <p className="text-caption1 text-gray-7">{this.state.error.message}</p>
        </div>
      );
    }
    return this.props.children;
  }
}

// ---- kiosk top bar ----------------------------------------------------------

interface KioskTopBarProps {
  serviceTypeName: string | null;
  planSeriesTitle: string | null;
  planTitle: string | null;
  showQr: boolean;
  remoteUrl: string | null;
  /** Name of the current display, shown only when there are multiple displays */
  displayName?: string | null;
}

function KioskTopBar({
  serviceTypeName,
  planSeriesTitle,
  planTitle,
  showQr,
  remoteUrl,
  displayName,
}: KioskTopBarProps) {
  // "Service type - Series title: Event title" — the series segment is omitted
  // when absent or identical to the event title to avoid duplication.
  const service = serviceTypeName ?? "—";
  const event = planTitle ?? "No plan";
  const lead =
    planSeriesTitle && planSeriesTitle !== planTitle
      ? `${service} - ${planSeriesTitle}`
      : service;
  const contextLabel = `${lead}: ${event}`;

  return (
    <div
      className="drag-region relative flex items-center h-10 shrink-0"
      style={{
        WebkitAppRegion: "drag",
        background: "rgba(0,0,0,0.50)",
        backdropFilter: "blur(20px) saturate(1.6)",
        borderBottom: "1px solid rgba(255,255,255,0.09)",
        // Faint top specular highlight for the glass sheen
        boxShadow: "inset 0 1px 0 rgba(255,255,255,0.07), 0 1px 8px rgba(0,0,0,0.40)",
      } as React.CSSProperties}
    >
      {/* Left: display name badge (only when multiple displays are configured).
          Offset clears the macOS traffic-light buttons overlaid at top-left. */}
      {displayName && (
        <div className="no-drag shrink-0 ml-[82px] relative z-10">
          <span
            className="text-caption1 font-medium text-white/40 select-none truncate"
            style={{ letterSpacing: "0.02em" }}
          >
            {displayName}
          </span>
        </div>
      )}

      {/* Centered context label — padded so it never collides with the side elements */}
      <div className="absolute inset-0 flex items-center justify-center px-32 pointer-events-none">
        <span
          className="text-caption1 font-medium text-white/55 truncate no-drag select-none tracking-wide"
          style={{ letterSpacing: "0.02em" }}
        >
          {contextLabel}
        </span>
      </div>

      {/* Right: compact QR glass pill (only when showQr) */}
      {showQr && remoteUrl && (
        <div className="no-drag shrink-0 ml-auto mr-3 relative z-10">
          <QrHint url={remoteUrl} compact />
        </div>
      )}
    </div>
  );
}

// ---- loading / empty states -------------------------------------------------

function KioskLoading() {
  return (
    <div className="flex flex-col items-center justify-center h-screen bg-[#080810] gap-3">
      <Loader2Icon className="size-8 text-gray-7 animate-spin" />
      <p className="text-headline text-gray-7">Loading stage…</p>
    </div>
  );
}

function KioskNotConfigured({ state, displayName }: { state: StageState; displayName: string | null }) {
  return (
    <div className="flex flex-col h-screen bg-[#080810]">
      <KioskTopBar
        serviceTypeName={state.serviceTypeName}
        planSeriesTitle={state.planSeriesTitle}
        planTitle={state.planTitle}
        showQr={state.showQr}
        remoteUrl={state.remoteUrl}
        displayName={displayName}
      />
      <div className="flex flex-col items-center justify-center flex-1 gap-4 px-12 text-center">
        <MonitorIcon className="size-12 text-gray-7" />
        <p className="text-title3 text-gray-9 font-semibold">Planning Center not configured</p>
        <p className="text-body text-gray-7">
          Open Settings (Cmd+,) or scan the QR code from a phone to add your PCO credentials.
        </p>
      </div>
    </div>
  );
}

function KioskEmpty({ state, displayName }: { state: StageState; displayName: string | null }) {
  return (
    <div className="flex flex-col h-screen bg-[#080810]">
      <KioskTopBar
        serviceTypeName={state.serviceTypeName}
        planSeriesTitle={state.planSeriesTitle}
        planTitle={state.planTitle}
        showQr={state.showQr}
        remoteUrl={state.remoteUrl}
        displayName={displayName}
      />
      <div className="flex flex-col items-center justify-center flex-1 gap-4 px-12 text-center">
        <MonitorIcon className="size-12 text-gray-7" />
        <p className="text-title3 text-gray-9 font-semibold">
          {state.planTitle ? state.planTitle : "No plan selected"}
        </p>
        <p className="text-body text-gray-7">No slots configured yet. Add slots in Settings.</p>
      </div>
    </div>
  );
}

function KioskError({ message }: { message: string }) {
  return (
    <div className="flex flex-col items-center justify-center h-screen bg-[#080810] gap-4 px-12 text-center">
      <AlertCircleIcon className="size-10 text-red-10" />
      <p className="text-title3 text-gray-9 font-semibold">Could not load stage state</p>
      <p className="text-caption1 text-gray-7">{message}</p>
    </div>
  );
}

// ---- main view --------------------------------------------------------------

export function StageView() {
  const [state, setState] = useState<StageState | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Determine which display this kiosk window is for.
  // The backend opens kiosk windows with ?display=<id>; primary window falls
  // back to "display-1" when no query param is present.
  const displayId = new URLSearchParams(window.location.search).get("display") ?? "display-1";

  // Hydrate on mount
  useEffect(() => {
    let cancelled = false;

    window.glazeAPI.glaze.ipc
      .invoke<StageState>("stage:getState")
      .then((s: StageState) => {
        if (cancelled) return;
        console.log("[StageView:hydrate]", {
          displayId,
          planId: s.planId,
          planTitle: s.planTitle,
          slotCount: s.slots.length,
          pcoConfigured: s.pcoConfigured,
          remoteUrl: s.remoteUrl,
          showQr: s.showQr,
        });
        setState(s);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        console.error("[StageView:hydrate] error", err);
        setError(String(err));
      })
      .finally(() => {
        if (!cancelled) setIsLoading(false);
      });

    return () => {
      cancelled = true;
    };
  // displayId is derived from location.search at mount; it never changes for a given window.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Subscribe to live updates
  useEffect(() => {
    const unsub = window.glazeAPI.glaze.ipc.onNotification(
      "stage:state-changed",
      (payload: unknown) => {
        const s = payload as StageState;
        console.log("[StageView:notification]", {
          displayId,
          planId: s.planId,
          slotCount: s.slots.length,
          pcoConfigured: s.pcoConfigured,
          showQr: s.showQr,
        });
        setState(s);
      },
    );
    return unsub;
  // displayId is stable for the lifetime of this window.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  if (isLoading) {
    return <KioskLoading />;
  }

  if (error) {
    return <KioskError message={error} />;
  }

  if (!state) {
    return <KioskError message="State is unavailable." />;
  }

  // Resolve the display's name for the top bar badge (only shown when >1 display).
  const multiDisplay = (state.displays?.length ?? 0) > 1;
  const currentDisplay = state.displays?.find((d) => d.id === displayId) ?? null;
  const displayName = multiDisplay ? (currentDisplay?.name ?? displayId) : null;

  if (!state.pcoConfigured) {
    return (
      <StageErrorBoundary>
        <KioskNotConfigured state={state} displayName={displayName} />
      </StageErrorBoundary>
    );
  }

  // Resolve slots for THIS display.
  // Prefer slotsByDisplay[displayId]; fall back to top-level slots (primary display compat).
  const displaySlots = state.slotsByDisplay?.[displayId] ?? state.slots ?? [];
  const sortedSlots = [...displaySlots].sort((a, b) => a.order - b.order);

  // Group into on-screen columns: a slot with stackWithPrevious joins the prior
  // column (stacked as rows); otherwise it starts a new column. This mirrors
  // dual-bay chargers where two people share one charger footprint.
  const columns: Slot[][] = [];
  for (const slot of sortedSlots) {
    if (slot.stackWithPrevious && columns.length > 0) {
      columns[columns.length - 1].push(slot);
    } else {
      columns.push([slot]);
    }
  }

  if (sortedSlots.length === 0) {
    return (
      <StageErrorBoundary>
        <KioskEmpty state={state} displayName={displayName} />
      </StageErrorBoundary>
    );
  }

  return (
    <StageErrorBoundary>
      {/* Deep dark gradient — defined in main-window.html; transparent here lets it show through */}
      <div className="flex flex-col h-screen overflow-hidden bg-transparent">
        {/* Top glass bar */}
        <KioskTopBar
          serviceTypeName={state.serviceTypeName}
          planSeriesTitle={state.planSeriesTitle}
          planTitle={state.planTitle}
          showQr={state.showQr}
          remoteUrl={state.remoteUrl}
          displayName={displayName}
        />

        {/* Horizontal row of columns. Each column holds one slot (full height)
            or several stacked slots (rows) sharing a charger footprint.
            SlotPanel provides its own p-1.5 gutter for consistent gaps. */}
        <div className="flex flex-1 min-h-0">
          {columns.map((column, ci) => (
            <div key={column[0]?.id ?? ci} className="flex flex-1 min-w-0 flex-col">
              {column.map((slot) => (
                <SlotPanel key={slot.id} slot={slot} />
              ))}
            </div>
          ))}
        </div>
      </div>
    </StageErrorBoundary>
  );
}
